# Initially generated by GitHub Copilot.
import re

from mb_cmn import bib_locales as tbn
from mb_cmn import file_io
from mb_cmn import hebrew_punctuation as hpu
from mb_cmn import paths
from mb_cmn import read_books_from_mam_parsed_plus as plus
from mb_cmn import template_names
from mb_cmn import ws_tmpl2 as wtp
from explicit_xataf import extract as doc_extract

_CLAUSE_BOUNDARY_RE = re.compile(r"(?:^|[;:.\n])\s*")
_LEADING_EQUALS_RE = re.compile(
    r"(?:^|[;:.\n])\s*=\s*([^<(\s][^<(\n=]{0,120}?)\s*(?=[(<\n=]|$)"
)
_LHS_EQUALS_RE = re.compile(r"(?:^|[;:.\n])\s*([^=<>\n]{1,120}?)\s*=")
# The geresh and gershayim of MAM's abbreviations and numerals, in their ASCII, typographic and
# Hebrew forms.  It holds the six characters themselves, not regex escapes, so that it serves as
# the body of a character class and as the list that _looks_authority_like_expression checks.
_GERESH_OR_GERSHAYIM = "'\"\u2019\u201d\u05f3\u05f4"
# A letter beside any of these is part of a longer word: a letter or digit of any script, a
# Hebrew point, accent or maqaf, the combining grapheme joiner that MAM has between marks, the
# hyphen of MAM's compounds, and a geresh or gershayim.  The prose pattern counts a single
# letter, bare or before a question or exclamation mark, only when none of them comes before
# it, and a bare letter only when none comes after it either: that is, when it stands alone, as
# a real siglum does.  It thereby misses a siglum quoted between apostrophes, such as ''ל'' at
# Song of Songs 5:2.
_IN_WORD_CHARS = (
    r"\w\u0591-\u05bd\u05bf\u05c1\u05c2\u05c4\u05c5\u05c7\u05be\ufb1e\u034f\-"
    + _GERESH_OR_GERSHAYIM
)
# One hyphenated part of a compound: letters or digits, with at most one geresh or gershayim
# inside, as in the second part of א-מ"ק.
_COMPOUND_PART = rf"[א-ת0-9]+(?:[{_GERESH_OR_GERSHAYIM}][א-ת0-9]+)?"
# The first alternative needs an abbreviation's geresh or gershayim.  Until 2026-10-29 another
# alternative, for כתי"ל and its kin, made the gershayim optional, and so it also counted the
# words כתיב, כתיבה and כתיבת.  The first, third and fourth alternatives take every hyphenated
# part of a compound.  Until 2026-10-30 they took at most one, and none with a geresh or
# gershayim, so that מ"ג-ק-מ was counted as מ"ג-ק, א-מ"ק as א-מ and ש1-כתיב as ש1.
_PROSE_ABBREV_RE = re.compile(
    rf"(?:[א-ת]+[{_GERESH_OR_GERSHAYIM}][א-ת0-9]+(?:-{_COMPOUND_PART})*|"
    r"[א-ת]+\([א-ת]+\)|"
    rf"[א-ת]+(?:-{_COMPOUND_PART})+|"
    rf"[א-ת]+\d+(?:-{_COMPOUND_PART})*|"
    rf"(?<![{_IN_WORD_CHARS}])[א-ת][?!]|"
    rf"(?<![{_IN_WORD_CHARS}])[א-ת](?![{_IN_WORD_CHARS}]))"
)
_TOKEN_SPLIT_RE = re.compile(r"[\s,]+")
# A run of Hebrew letters and marks, with the combining grapheme joiner that MAM puts between two
# marks, so that a pointed word holding one is removed whole.  Until 2026-10-30 the joiner split
# such a word in two, and the removal left the joiner behind.
_HEBREW_CLUSTER_RE = re.compile(
    r"[\u05d0-\u05ea\u0591-\u05bd\u05bf\u05c1\u05c2\u05c4\u05c5\u05c7\u05be\ufb1e\u034f]+"
)
_HAS_POINT_RE = re.compile(r"[\u0591-\u05bd\u05bf\u05c1\u05c2\u05c4\u05c5\u05c7\ufb1e]")


def build_inventory(mam_parsed_path=None):
    # None rather than a default of paths.mam_parsed_path(), because a default argument is
    # evaluated at IMPORT time and that call raises when the sibling is missing.  Since
    # main_0_mega.py imports main_sigil_inventory at module top, a checkout without
    # MAM-parsed would then fail to import the whole mega before running a single step.
    if mam_parsed_path is None:
        mam_parsed_path = paths.mam_parsed_path()
    books_mpu = plus.read_parsed_plus_bk39s(mam_parsed_path=mam_parsed_path)
    expression_examples = {}
    token_examples = {}
    prose_examples = {}
    note_count = 0
    matched_note_count = 0
    for bkid in tbn.ALL_BK39_IDS:
        if bkid not in books_mpu:
            continue
        verses = books_mpu[bkid]["verses_plus"]
        for bcvt, minirow in verses.items():
            ref = _bcvt_to_ref(bcvt)
            for column_name, column in (("CP", minirow.CP), ("EP", minirow.EP)):
                for tmpl in doc_extract.find_docnote_tmpls(column):
                    note_count += 1
                    note_text = _note_text(tmpl)
                    if note_text.strip() == "":
                        continue
                    found_any = False
                    for expression in _leading_equals_expressions(note_text):
                        _add_example(
                            expression_examples,
                            expression,
                            ref,
                            column_name,
                            note_text,
                            "leading-equals",
                        )
                        for token in _split_expression_tokens(expression):
                            _add_example(
                                token_examples,
                                token,
                                ref,
                                column_name,
                                note_text,
                                "leading-equals-token",
                            )
                        found_any = True
                    for expression in _lhs_equals_expressions(note_text):
                        _add_example(
                            expression_examples,
                            expression,
                            ref,
                            column_name,
                            note_text,
                            "lhs-equals",
                        )
                        for token in _split_expression_tokens(expression):
                            _add_example(
                                token_examples,
                                token,
                                ref,
                                column_name,
                                note_text,
                                "lhs-equals-token",
                            )
                        found_any = True
                    prose_scan_text = _without_pointed_hebrew(note_text)
                    for token in _prose_abbreviation_tokens(prose_scan_text):
                        _add_example(
                            prose_examples,
                            token,
                            ref,
                            column_name,
                            note_text,
                            "prose-token",
                        )
                        found_any = True
                    if found_any:
                        matched_note_count += 1
    return {
        "header": {
            "description": "Inventory of sigil-like material found in נוסח notes across MAM-parsed-plus.",
            "counts": {
                "notes_scanned": note_count,
                "notes_with_matches": matched_note_count,
                "distinct_expressions": len(expression_examples),
                "distinct_expression_tokens": len(token_examples),
                "distinct_prose_tokens": len(prose_examples),
            },
            "categories": {
                "expressions": "Raw candidate authority expressions captured near = in note text.",
                "expression_tokens": "Candidate sigil-like tokens split from those expressions.",
                "prose_tokens": 'Sigil-like abbreviations found in prose contexts, such as כתי"ק-מ.',
            },
        },
        "expressions": _sorted_inventory(expression_examples),
        "expression_tokens": _sorted_inventory(token_examples),
        "prose_tokens": _sorted_inventory(prose_examples),
    }


def write_inventory(
    out_path="out/sigil-inventory.json",
    mam_parsed_path=None,
):
    # out_path stays cwd-relative on purpose: every caller runs from the repo root, main_0_mega.py
    # included.  mam_parsed_path is None for the reason build_inventory's comment gives, and is
    # passed straight through so that resolution happens in one place.
    inventory = build_inventory(mam_parsed_path)
    file_io.json_dump_to_file_path(inventory, out_path)
    return inventory


def _bcvt_to_ref(bcvt):
    bk39id, chnu, vrnu = tbn.bcvt_get_bcv_triple(bcvt)
    return f"{bk39id} {chnu}:{vrnu}"


def _note_text(tmpl):
    arg2 = wtp.template_param_val(tmpl, "2")
    return _note_node_to_text(arg2)


def _note_node_to_text(node):
    """Render the visible text of a current MAM documentation-note body."""
    if isinstance(node, str):
        return node
    if isinstance(node, list):
        return "".join(_note_node_to_text(item) for item in node)
    if not isinstance(node, dict) or not wtp.is_template(node):
        raise TypeError(f"unclassified MAM note-body node: {type(node).__name__}")

    template_names.validate_current_plus_template(node)
    name = wtp.template_name(node)
    if name == "ש":
        return "\n"
    if name in {
        "מודגש",
        "מ:אות-ג",
        "מ:אות-ק",
        "מ:אות תלויה",
        template_names.SLH_WORD,
    }:
        return _note_node_to_text(wtp.template_param_val(node, "1"))
    if name in {"מ:קישור בהערה", "מ:קישור פנימי בהערה"}:
        return _note_node_to_text(wtp.template_param_val(node, "2"))
    if name in {"מ:לגרמיה-2", "מ:פסק"}:
        return hpu.PASOLEG
    raise ValueError(f"unclassified MAM note-body template: {name!r}")


def _without_pointed_hebrew(text):
    """Remove Hebrew clusters that contain a point or accent."""

    def replace_cluster(match):
        cluster = match.group(0)
        return "" if _HAS_POINT_RE.search(cluster) else cluster

    return _HEBREW_CLUSTER_RE.sub(replace_cluster, text)


def _leading_equals_expressions(note_text):
    expressions = []
    for match in _LEADING_EQUALS_RE.finditer(note_text):
        expression = _clean_expression(match.group(1))
        if expression != "":
            expressions.append(expression)
    return expressions


def _lhs_equals_expressions(note_text):
    expressions = []
    for match in _LHS_EQUALS_RE.finditer(note_text):
        expression = _clean_expression(match.group(1))
        if _looks_authority_like_expression(expression):
            expressions.append(expression)
    return expressions


def _clean_expression(expression):
    cleaned = expression.strip()
    cleaned = cleaned.strip("<>")
    return cleaned


def _looks_authority_like_expression(expression):
    if expression == "":
        return False
    # Until 2026-10-30 this accepted only the ASCII geresh and gershayim and the Hebrew
    # gershayim, and so rejected שי”ן and ואח”כ, typed with a typographic gershayim.
    if any(
        char in expression
        for char in (*_GERESH_OR_GERSHAYIM, "-", "(", ")", ",", "?", "!")
    ):
        return True
    if re.search(r"\d", expression):
        return True
    if expression in {
        "א",
        "ב",
        "ג",
        "ה",
        "ו",
        "ז",
        "ח",
        "ט",
        "י",
        "כ",
        "ל",
        "מ",
        "נ",
        "ס",
        "ע",
        "פ",
        "צ",
        "ק",
        "ר",
        "ש",
        "ת",
    }:
        return True
    if any(
        expression.startswith(prefix)
        for prefix in ("מסורת", "מסורות", "שיטת", "בדפוסים", 'במ"ש', "בכתי", "כתי")
    ):
        return True
    return False


def _split_expression_tokens(expression):
    tokens = []
    for token in _TOKEN_SPLIT_RE.split(expression):
        filtered = _without_pointed_hebrew(token)
        cleaned = filtered.strip()
        if cleaned == "":
            continue
        if filtered != token and not any(char.isalnum() for char in cleaned):
            continue
        if cleaned == "וכן":
            continue
        tokens.append(cleaned)
    return tokens


def _prose_abbreviation_tokens(note_text):
    tokens = []
    for match in _PROSE_ABBREV_RE.finditer(note_text):
        token = match.group(0).strip()
        if _looks_authority_like_expression(token):
            tokens.append(token)
    return tokens


def _add_example(inventory, key, ref, column_name, note_text, source_kind):
    item = inventory.get(key)
    example = {
        "ref": ref,
        "column": column_name,
        "source_kind": source_kind,
        "note_text": note_text,
    }
    if item is None:
        inventory[key] = {"count": 1, "examples": [example]}
        return
    item["count"] += 1
    if len(item["examples"]) < 5:
        item["examples"].append(example)


def _sorted_inventory(inventory):
    out = []
    for key, value in sorted(
        inventory.items(), key=lambda pair: (-pair[1]["count"], pair[0])
    ):
        out.append({"item": key, **value})
    return out
